/// <summary>
/// CB202_SalesQuotaMinMax
/// Process sales order line quota
/// </summary>
internal final class METSalesLineQuotaProcess
{
    SalesTable    salesTable;
    METSalesTable metSalesTable;
    SalesLine     salesLine;

}

Method.Source:
/// <summary>
/// Public construct method to execute sales order line quota
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <param name = "_metSalesTable">Sales order header additional fields</param>
/// <param name = "_salesLine">Sales order line to process</param>
/// <returns>Instance of <c>METSalesLineQuotaProcess</c></returns>
public static METSalesLineQuotaProcess construct(SalesTable _salesTable, METSalesTable _metSalesTable, SalesLine _salesLine)
{
    return new METSalesLineQuotaProcess(_salesTable, _metSalesTable, _salesLine);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <param name = "_metSalesTable">Sales order header additional fields</param>
/// <param name = "_salesLine">Sales order line to process</param>
protected void new(SalesTable _salesTable, METSalesTable _metSalesTable, SalesLine _salesLine)
{
    salesTable      = _salesTable;
    metSalesTable   = _metSalesTable;
    salesLine       = _salesLine;        
}

/// <summary>
/// Execute quotas line logic and create SA link 
/// </summary>
/// <returns>True if quota logic executed; otherwise, false.</returns>
public boolean run()
{
    SalesAgreementHeader    salesAgreementHeader;
    ReasonCode              reasonCode;
    AgreementLine           agreementLine;
    METSalesLine            metSalesLine = METSalesLine::find(salesLine.RecId, true);
    AgreementClassification agreementClassification;
    boolean                 cancelLine = false, qtyUpdated = false;

    // if the line is already linked to SA, do not apply quota logic again
    if (salesLine.MatchingAgreementLine)
    {
        return false;
    }

    METAgreementLineSearch agreementLineSearch = METAgreementLineSearch::construct(salesTable, salesLine);
    METAgreementLineSearchResult result = agreementLineSearch.run();

    if (result)
    {
        salesAgreementHeader = result.getSalesAgreementHeader();
        agreementLine = result.getAgreementLine();
        agreementClassification = result.getAgreementClassification();

        metSalesLine.OrderedQuantity = salesLine.SalesQty;

        reasonCode = agreementClassification.METCustReason;

        salesLine.selectForUpdate(true);

        // Product value commitment or vendor category value commitment
        if (salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductVolume
        ||  salesAgreementHeader.DefaultAgreementLineType == CommitmentType::METVendorCategoryProductVolume
        ||  salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductRootCategory
        ||  salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductCategory)
        {
            Amount      remainingAmountInAgreementLine = agreementLine.METgetAgreementLineRemaining();

            // Bug 280019: CB202 Quota is not getting applied in PBMSQA as per new logic
            // Added logic to round down the quantity to avoid quota going into negative when salesQtyModified() rounds the qty
            SalesQty reducedQty;

            if (salesLine.SalesPrice != 0)
            {
                reducedQty = roundDown(remainingAmountInAgreementLine / salesLine.SalesPrice, 1);
            }

            // sales agreement completely fulfilled or reducedQty is 0 and we have a unit price
            if (!remainingAmountInAgreementLine || (!reducedQty && salesLine.SalesPrice))                
            {
                cancelLine = true;
                //metSalesLine.ReducedQuantity    = salesLine.SalesQty;
                metSalesLine.ReasonId           = reasonCode;
            }
            // SA fulfilment remaining amount < salesLine.LineAmount
            else if (remainingAmountInAgreementLine < salesLine.LineAmount)
            {
                salesLine.SalesQty              = reducedQty;
                salesLine.SalesPrice            = salesLine.SalesPrice;
                salesLine.LineAmount            = salesLine.SalesPrice * reducedQty;
                metSalesLine.ReasonId           = reasonCode;
                //metSalesLine.ReducedQuantity    = metSalesLine.OrderedQuantity - salesLine.SalesQty;

                qtyUpdated = true;
            }
        }
        // Product qty commitment
        else if(salesAgreementHeader.DefaultAgreementLineType == CommitmentType::ProductQuantity)
        {                
            Qty qtyRemainInAgreementLine = agreementLine.METgetAgreementLineRemaining();

            // sales agreement completely fulfilled
            if (!qtyRemainInAgreementLine)
            {
                cancelLine = true;
                //metSalesLine.ReducedQuantity    = salesLine.SalesQty;
                metSalesLine.ReasonId           = reasonCode;
            }
            // SA fulfilment remaining qty < salesLine.SalesQty
            else if (qtyRemainInAgreementLine != 0 && qtyRemainInAgreementLine < salesLine.SalesQty)
            {
                salesLine.SalesQty              = qtyRemainInAgreementLine;
                metSalesLine.ReasonId           = reasonCode;
                //metSalesLine.ReducedQuantity    = metSalesLine.OrderedQuantity - salesLine.SalesQty;
                qtyUpdated = true;
            }
        }

        if (qtyUpdated)
        {
            salesLine.salesQtyModified();
        }
        //salesLine.update(); // salesLine.update() update is called in metCancelSalesOrderLine and SalesTableForm::createAgreementLinkServer
        metSalesLine.update();

        if (cancelLine)
        {
            salesLine.metCancelSalesOrderLine();
        }
        else if (metSalesTable.LinkedSalesAgreement == true && salesLine.MatchingAgreementLine == 0 && agreementLine.RecId) /// CB_202 SalesQuota changes by Akshay
        {
            // Insert the sales agreement number onto the sales order line via the update line > create link menu option
            // this will then trigger the enforce quota code that is described below and if required the line quantity will be reduced or the line cancelled.
            ttsbegin;
            SalesTableForm::createAgreementLinkServer(salesLine, agreementLine);
            ttscommit;
        }
    }
    return true;
}
